dsl:
name: pool
bar: 1h
strategy_pool:
  members:
    - {id: a, strategy: s_a}
    - {id: c, strategy: s_c}
    - {id: s, strategy: s_s}
  allocation:
    method: drift
    ratios: {a: 0.4, c: 0.3, s: 0.3}
    sides: {long: {rebalance: every_bar}}
  freeze: {watch: long, window_bars: 1, threshold: 0.002, bars: 2}
  fees: {spot_bps: 10, swap_bps: 5}
